<div class="card-box"><h4>Line Items</h4><div class="manual-note"><i class="fa fa-info-circle"></i> Items are entered manually for this quotation. No spare-parts master is used or updated.</div><div class="table-responsive"><table class="table table-bordered items-table"><thead><tr><th>#</th><th>Description *</th><th>HSN</th><th>Qty *</th><th>Unit</th><th>Rate *</th><th>Disc. %</th><th>GST %</th><th>Total</th><th></th></tr></thead><tbody id="items">
<?php $rows=$items?:array((object)array('item_description'=>'','hsn_code'=>'','quantity'=>1,'unit'=>'Nos','unit_rate'=>0,'discount_percent'=>0,'gst_percent'=>18)); foreach($rows as $i=>$item){ ?><tr><td class="line-no"><?php echo $i+1; ?></td><td><textarea name="item_description[]" class="form-control description" required><?php echo html_escape($item->item_description); ?></textarea></td><td><input name="hsn_code[]" class="form-control" value="<?php echo html_escape($item->hsn_code); ?>"></td><td><input type="number" min=".001" step=".001" name="quantity[]" class="form-control calc qty" value="<?php echo html_escape($item->quantity); ?>" required></td><td><input name="unit[]" class="form-control" value="<?php echo html_escape($item->unit); ?>"></td><td><input type="number" min="0" step=".01" name="unit_rate[]" class="form-control calc rate" value="<?php echo html_escape($item->unit_rate); ?>" required></td><td><input type="number" min="0" max="100" step=".01" name="discount_percent[]" class="form-control calc discount" value="<?php echo html_escape($item->discount_percent); ?>"></td><td><input type="number" min="0" max="100" step=".01" name="gst_percent[]" class="form-control calc gst" value="<?php echo html_escape($item->gst_percent); ?>"></td><td class="line-total text-right">0.00</td><td><button type="button" class="btn btn-danger btn-xs remove"><i class="fa fa-trash"></i></button></td></tr><?php } ?></tbody></table></div><button type="button" id="add" class="btn btn-success"><i class="fa fa-plus"></i> Add Manual Item</button></div>
