(function(){function n(v){v=parseFloat(v);return isNaN(v)?0:v}function calc(){var sub=0,disc=0,tax=0;$('#items tr').each(function(){var q=n($('.qty',this).val()),r=n($('.rate',this).val()),d=n($('.discount',this).val()),g=n($('.gst',this).val()),gross=q*r,da=gross*d/100,taxable=gross-da,ga=taxable*g/100;sub+=gross;disc+=da;tax+=ga;$('.line-total',this).text((taxable+ga).toFixed(2))});$('#sub').text(sub.toFixed(2));$('#disc').text(disc.toFixed(2));$('#tax').text(tax.toFixed(2));$('#grand').text((sub-disc+tax).toFixed(2))}function renumber(){$('#items tr').each(function(i){$('.line-no',this).text(i+1)})}$(document).on('input','.calc',calc).on('click','.remove',function(){if($('#items tr').length>1){$(this).closest('tr').remove();renumber();calc()}});$('#add').click(function(){var row=$('#items tr:first').clone();$('textarea,input',row).val('');$('.qty',row).val('1');$('input[name="unit[]"]',row).val('Nos');$('.discount',row).val('0');$('.gst',row).val('18');$('.line-total',row).text('0.00');$('#items').append(row);renumber();calc()});calc()})();
</script></body></html>
